from __future__ import annotations

import sys


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    sys.setrecursionlimit(100000)

    DIV0 = "#DIV/0!"
    CYCLE = "#CYCLE!"

    class Parser:
        def __init__(self, toks):
            self.toks = toks
            self.i = 0

        def peek(self, k=0):
            j = self.i + k
            if j < len(self.toks):
                return self.toks[j]
            return ("END", "")

        def parse(self):
            return self.expr()

        @staticmethod
        def is_cell(name):
            if len(name) not in (2, 3):
                return False
            if not ("A" <= name[0] <= "Z"):
                return False
            if not ("1" <= name[1] <= "9"):
                return False
            return len(name) == 2 or "0" <= name[2] <= "9"

        def expr(self):
            node = self.term()
            while self.peek()[0] == "OP" and self.peek()[1] in ("+", "-"):
                op = self.peek()[1]
                self.i += 1
                node = ("bin", op, node, self.term())
            return node

        def term(self):
            node = self.unary()
            while self.peek()[0] == "OP" and self.peek()[1] in ("*", "/"):
                op = self.peek()[1]
                self.i += 1
                node = ("bin", op, node, self.unary())
            return node

        def unary(self):
            if self.peek() == ("OP", "-"):
                self.i += 1
                return ("neg", self.unary())
            return self.atom()

        def atom(self):
            t = self.peek()
            if t[0] == "NUM":
                self.i += 1
                return ("num", t[1])
            if t[0] == "NAME":
                name = t[1]
                if name in ("SUM", "MIN", "MAX", "IF") and self.peek(1) == ("OP", "("):
                    self.i += 2
                    if name == "IF":
                        return self.if_body()
                    return self.agg_body(name)
                if self.is_cell(name):
                    self.i += 1
                    return ("cell", name)
                self.i += 1
                return ("num", 0)
            if t == ("OP", "("):
                self.i += 1
                node = self.expr()
                if self.peek() == ("OP", ")"):
                    self.i += 1
                return node
            self.i += 1
            return ("num", 0)

        def agg_body(self, fname):
            args = []
            while True:
                args.append(self.agg_arg())
                if self.peek() == ("OP", ","):
                    self.i += 1
                elif self.peek() == ("OP", ")"):
                    self.i += 1
                    break
                else:
                    break
            return ("agg", fname, args)

        def agg_arg(self):
            a = self.peek()
            colon = self.peek(1)
            b = self.peek(2)
            if (
                a[0] == "NAME"
                and self.is_cell(a[1])
                and colon == ("OP", ":")
                and b[0] == "NAME"
                and self.is_cell(b[1])
            ):
                self.i += 3
                return ("range", a[1], b[1])
            return ("expr", self.expr())

        def if_body(self):
            left = self.expr()
            op = self.peek()
            if op[0] == "OP" and op[1] in ("=", "<>", "<", "<=", ">", ">="):
                self.i += 1
                cop = op[1]
            else:
                cop = "="
            right = self.expr()
            if self.peek() == ("OP", ","):
                self.i += 1
            then = self.expr()
            if self.peek() == ("OP", ","):
                self.i += 1
            els = self.expr()
            if self.peek() == ("OP", ")"):
                self.i += 1
            return ("if", left, cop, right, then, els)

    def tokenize(text):
        toks = []
        i = 0
        n = len(text)
        while i < n:
            ch = text[i]
            if ch.isspace():
                i += 1
                continue
            if "0" <= ch <= "9":
                j = i
                while j < n and "0" <= text[j] <= "9":
                    j += 1
                toks.append(("NUM", int(text[i:j])))
                i = j
                continue
            if "A" <= ch <= "Z" or "a" <= ch <= "z":
                j = i
                while j < n and ("A" <= text[j] <= "Z" or "a" <= text[j] <= "z"):
                    j += 1
                k = j
                while k < n and "0" <= text[k] <= "9":
                    k += 1
                if k > j:
                    toks.append(("NAME", text[i:k]))
                    i = k
                else:
                    toks.append(("NAME", text[i:j]))
                    i = j
                continue
            two = text[i:i + 2]
            if two in ("<>", "<=", ">="):
                toks.append(("OP", two))
                i += 2
                continue
            if ch in "+-*/(),:=<>":
                toks.append(("OP", ch))
                i += 1
                continue
            i += 1
        toks.append(("END", ""))
        return toks

    def parse_formula(text):
        return Parser(tokenize(text)).parse()

    def cell_rc(name):
        return ord(name[0]) - 65, int(name[1:])

    values = {}
    in_progress = set()

    def ev(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "cell":
            return get_cell(node[1])
        if kind == "neg":
            v = ev(node[1])
            return v if isinstance(v, str) else -v
        if kind == "bin":
            left = ev(node[2])
            if isinstance(left, str):
                return left
            right = ev(node[3])
            if isinstance(right, str):
                return right
            op = node[1]
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return DIV0
            q = abs(left) // abs(right)
            if (left < 0) != (right < 0):
                q = -q
            return q
        if kind == "agg":
            return ev_agg(node)
        if kind == "if":
            return ev_if(node)
        return 0

    def ev_agg(node):
        vals = []
        for arg in node[2]:
            if arg[0] == "range":
                c1, r1 = cell_rc(arg[1])
                c2, r2 = cell_rc(arg[2])
                rlo, rhi = min(r1, r2), max(r1, r2)
                clo, chi = min(c1, c2), max(c1, c2)
                for row in range(rlo, rhi + 1):
                    for col in range(clo, chi + 1):
                        name = chr(65 + col) + str(row)
                        if name in cells:
                            v = get_cell(name)
                            if isinstance(v, str):
                                return v
                            vals.append(v)
            else:
                v = ev(arg[1])
                if isinstance(v, str):
                    return v
                vals.append(v)
        if node[1] == "SUM":
            return sum(vals)
        if node[1] == "MIN":
            return min(vals) if vals else 0
        return max(vals) if vals else 0

    def ev_if(node):
        left = ev(node[1])
        if isinstance(left, str):
            return left
        right = ev(node[3])
        if isinstance(right, str):
            return right
        op = node[2]
        if op == "=":
            cond = left == right
        elif op == "<>":
            cond = left != right
        elif op == "<":
            cond = left < right
        elif op == "<=":
            cond = left <= right
        elif op == ">":
            cond = left > right
        else:
            cond = left >= right
        return ev(node[4] if cond else node[5])

    def eval_content(name):
        text = cells[name]
        if text.startswith("="):
            return ev(parse_formula(text[1:]))
        return int(text)

    def get_cell(name):
        if name in values:
            return values[name]
        if name in in_progress:
            return CYCLE
        if name not in cells:
            return 0
        in_progress.add(name)
        try:
            val = eval_content(name)
        finally:
            in_progress.remove(name)
        values[name] = val
        return val

    for name in cells:
        get_cell(name)

    return {name: values[name] for name in cells}
